SELECT q.*, d.db_name AS datasource_name, t.table_name, t.table_name_cn, CASE WHEN EXISTS (SELECT 1 FROM dq_quality_task_rule_t qp WHERE qp.tenant_id=#{tenantId} AND qp.task_id=q.tid AND qp.is_del=0 AND qp.rule_type='PROFILE') THEN 'PROFILE' ELSE 'QUALITY' END AS task_kind, r.status AS latest_run_status, CASE WHEN r.checked_count>0 THEN r.quality_score ELSE NULL END AS latest_score, r.violation_count AS latest_violation_count, (SELECT COUNT(*) FROM dq_quality_task_rule_t qr WHERE qr.tenant_id=#{tenantId} AND qr.task_id=q.tid AND qr.is_del=0) AS rule_count, CASE WHEN d.tid IS NULL OR t.tid IS NULL THEN 1 ELSE 0 END AS repair_required FROM dq_quality_task_t q LEFT JOIN db_datasource_t d ON d.tid = q.datasource_id AND d.tenant_id = #{tenantId} AND d.is_del = 0 LEFT JOIN db_table_t t ON t.tid = q.table_id AND t.tenant_id = #{tenantId} AND t.is_del = 0 LEFT JOIN dq_quality_run_t r ON r.tid = q.last_run_id AND r.tenant_id = #{tenantId} WHERE q.tenant_id = #{tenantId} AND q.is_del = 0
AND (CASE WHEN EXISTS (SELECT 1 FROM dq_quality_task_rule_t qp WHERE qp.tenant_id=#{tenantId} AND qp.task_id=q.tid AND qp.is_del=0 AND qp.rule_type='PROFILE') THEN 'PROFILE' ELSE 'QUALITY' END) = #{kind}
AND q.status = #{status}
AND (q.task_name LIKE CONCAT('%', #{keyword}, '%') OR q.task_code LIKE CONCAT('%', #{keyword}, '%') OR d.db_name LIKE CONCAT('%', #{keyword}, '%') OR t.table_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY q.updated_time DESC

SELECT r.*, q.task_name, q.task_code, d.db_name AS datasource_name,
       t.table_name, t.table_name_cn,
       r.run_kind AS task_kind
FROM dq_quality_run_t r
JOIN dq_quality_task_t q ON q.tid = r.task_id AND q.tenant_id = #{tenantId}
LEFT JOIN db_datasource_t d ON d.tid = q.datasource_id AND d.tenant_id = #{tenantId}
LEFT JOIN db_table_t t ON t.tid = q.table_id AND t.tenant_id = #{tenantId}
WHERE r.tenant_id = #{tenantId} AND r.is_del = 0

    AND r.run_kind = #{kind}


    AND r.status = #{status}


    AND (q.task_name LIKE CONCAT('%', #{keyword}, '%')
      OR q.task_code LIKE CONCAT('%', #{keyword}, '%')
      OR t.table_name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY r.created_time DESC

SELECT i.*, m.rule_name, m.rule_type, m.quality_dimension
FROM dq_quality_issue_sample_t i
JOIN dq_quality_metric_t m ON m.run_id = i.run_id
  AND m.task_rule_id = i.task_rule_id AND m.tenant_id = #{tenantId}
WHERE i.tenant_id = #{tenantId} AND i.run_id = #{runId}
AND i.issue_status = #{status}
AND i.severity = #{severity}
ORDER BY i.created_time DESC

SELECT r.*, q.task_name, q.task_code, q.datasource_id, q.table_id, q.shard_key,
       d.db_name AS datasource_name, t.table_name, t.table_name_cn
FROM dq_quality_run_t r
JOIN dq_quality_task_t q ON q.tid = r.task_id AND q.tenant_id = #{tenantId}
LEFT JOIN db_datasource_t d ON d.tid = q.datasource_id AND d.tenant_id = #{tenantId}
LEFT JOIN db_table_t t ON t.tid = q.table_id AND t.tenant_id = #{tenantId}
WHERE r.tenant_id = #{tenantId} AND r.tid = #{runId} AND r.is_del = 0

SELECT * FROM dq_quality_metric_t
WHERE tenant_id = #{tenantId} AND run_id = #{runId}
ORDER BY quality_dimension, rule_name

SELECT * FROM dq_quality_run_shard_t
WHERE tenant_id = #{tenantId} AND run_id = #{runId}
ORDER BY shard_no

mapper.update:
UPDATE dq_quality_run_shard_t SET status='RUNNING',attempt=attempt+1,worker_id=#{workerId},
  lease_at=#{now},started_at=COALESCE(started_at,#{now}),updated_time=#{now}
WHERE tid=#{shardId} AND status='PENDING'

UPDATE dq_quality_run_shard_t SET status='COMPLETED',row_count=#{rowCount},checked_count=#{checked},
  violation_count=#{violations},finished_at=#{now},updated_time=#{now}
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND tid=#{shardId} AND status='RUNNING'

UPDATE dq_quality_run_shard_t SET status=#{status},error_message=#{message},worker_id=NULL,lease_at=NULL,
  finished_at=CASE WHEN #{status}='FAILED' THEN #{now} ELSE NULL END,updated_time=#{now}
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND tid=#{shardId}

UPDATE dq_quality_metric_t SET checked_count=checked_count+#{checked},
  violation_count=violation_count+#{violations},profile_json=COALESCE(#{profileJson},profile_json),updated_time=#{now}
WHERE tenant_id=#{tenantId} AND run_id=#{runId} AND task_rule_id=#{ruleId}

UPDATE dq_quality_metric_t SET pass_rate=CASE WHEN checked_count=0 THEN 0 ELSE (checked_count-LEAST(checked_count,violation_count))*100.0/checked_count END,
    score=CASE WHEN checked_count=0 THEN 0 ELSE (checked_count-LEAST(checked_count,violation_count))*100.0/checked_count END
WHERE tenant_id=#{tenantId} AND run_id=#{runId}

UPDATE dq_quality_run_t SET status=#{status},shard_completed=#{shardCompleted},row_count=#{rowCount},
  checked_count=#{checked},violation_count=#{violations},quality_score=#{score},finished_at=#{now},updated_time=#{now}
WHERE tenant_id=#{tenantId} AND tid=#{runId} AND status='RUNNING'

UPDATE dq_quality_run_t SET status='FAILED',error_code=#{code},error_message=#{message},error_detail=#{detail},
  trace_id=#{traceId},finished_at=#{now},updated_time=#{now}
WHERE tenant_id=#{tenantId} AND tid=#{runId} AND status IN ('PENDING','INITIALIZING','RUNNING')

UPDATE dq_quality_run_shard_t
SET status=CASE WHEN attempt >= #{maxAttempts} THEN 'FAILED' ELSE 'PENDING' END,
    worker_id=NULL,lease_at=NULL,updated_time=#{staleBefore}
WHERE status='RUNNING' AND lease_at < #{staleBefore}
